using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");

// Load raw data with Churned as string ("Yes"/"No"), then map to boolean label
var rawData = mlContext.Data.LoadFromTextFile<CustomerDataRaw>(dataPath, separatorChar: ',', hasHeader: true);
var data = mlContext.Transforms.CustomMapping<CustomerDataRaw, LabelMapped>(
    (input, output) => output.Label = input.Churned == "Yes", contractName: null)
    .Fit(rawData).Transform(rawData);

var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerDataRaw.Region))
    .Append(mlContext.Transforms.NormalizeMinMax(nameof(CustomerDataRaw.Age)))
    .Append(mlContext.Transforms.NormalizeMinMax(nameof(CustomerDataRaw.Income)))
    .Append(mlContext.Transforms.NormalizeMinMax(nameof(CustomerDataRaw.PurchaseHistory)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerDataRaw.Age), nameof(CustomerDataRaw.Income),
        "RegionEncoded", nameof(CustomerDataRaw.PurchaseHistory)))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label", featureColumnName: "Features"));

var model = pipeline.Fit(split.TrainSet);

// Evaluate — use cross-validation for small datasets, train/test split for larger ones
var rowCount = (int)rawData.GetColumn<float>(nameof(CustomerDataRaw.Age)).Count();
if (rowCount >= 20)
{
    var predictions = model.Transform(split.TestSet);
    var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
    Console.WriteLine($"AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
}
else
{
    var cvResults = mlContext.BinaryClassification.CrossValidate(data, pipeline, numberOfFolds: 3, labelColumnName: "Label");
    var avgAuc = cvResults.Average(r => r.Metrics.AreaUnderRocCurve);
    var avgAcc = cvResults.Average(r => r.Metrics.Accuracy);
    Console.WriteLine($"Cross-validated (3-fold) — AUC: {avgAuc:F4}, Accuracy: {avgAcc:F4}");
    Console.WriteLine("Note: dataset has few rows; add more data for reliable metrics.");
}

var modelPath = Path.Combine(AppContext.BaseDirectory, "ChurnModel.zip");
mlContext.Model.Save(model, data.Schema, modelPath);

builder.Services.AddPredictionEnginePool<CustomerInput, ChurnPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapPost("/predict", (PredictionEnginePool<CustomerInput, ChurnPrediction> pool, CustomerInput input) =>
{
    var prediction = pool.Predict(input);
    return Results.Ok(new
    {
        WillChurn = prediction.PredictedLabel,
        Probability = prediction.Probability
    });
});

app.Run();

// Raw CSV row — Churned is a string ("Yes"/"No")
public class CustomerDataRaw
{
    [LoadColumn(0)] public float Age { get; set; }
    [LoadColumn(1)] public float Income { get; set; }
    [LoadColumn(2)] public string Region { get; set; } = "";
    [LoadColumn(3)] public float PurchaseHistory { get; set; }
    [LoadColumn(4)] public string Churned { get; set; } = "";
}

// Mapped label for training
public class LabelMapped
{
    public bool Label { get; set; }
}

// Prediction input (no label column needed)
public class CustomerInput
{
